{"file_path":"src/ini.js","content":"/** The INI reader: dotted keys, the raw text of each value, and the position it was written at. */

const NAME = /^[A-Za-z0-9_.-]+$/

/** One refusal of an INI line, carrying the 1-based line and column it was read at. */
export class IniError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'IniError'
    this.line = line
    this.column = column
  }
}

/** The 1-based column of the first non-space character of `raw`. */
function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * The 1-based column a value was written at: its first character, or, when the value is
 * empty, one past the line's last non-space character.
 * @param {string} raw - the whole raw line.
 * @param {number} split - the index of the `=` within the trimmed line.
 * @param {string} rest - the trimmed line's text after the `=`, untrimmed.
 * @returns {number} the 1-based column.
 */
function valueColumn(raw, split, rest) {
  if (rest.trim() === '') return raw.trimEnd().length + 1
  return indent(raw) + split + 1 + (rest.length - rest.trimStart().length)
}

/** Split text into its lines, dropping the empty one a trailing newline leaves behind. */
export function lines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Parse INI text into its settings.
 * @param {string} text - the file's whole text.
 * @returns {Map<string, {text: string, line: number, column: number}>} each dotted key's raw
 *   value with the position it was written at, in the order the file writes them.
 * @throws {IniError} on the first line the grammar refuses.
 */
export function parse(text) {
  const values = new Map()
  let section = ''
  for (const [index, raw] of lines(text).entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#') || trimmed.startsWith(';')) continue
    if (trimmed.startsWith('[')) {
      if (!trimmed.endsWith(']')) throw new IniError(line, raw.trimEnd().length + 1, 'expected "]"')
      const name = trimmed.slice(1, -1)
      if (name === '') throw new IniError(line, indent(raw) + 1, 'expected a section name')
      if (!NAME.test(name)) throw new IniError(line, indent(raw) + 1, `invalid section name ${name}`)
      section = name
      continue
    }
    const split = trimmed.indexOf('=')
    if (split === -1) throw new IniError(line, indent(raw), 'expected a section header or key = value')
    const key = trimmed.slice(0, split).trim()
    if (key === '') throw new IniError(line, indent(raw) + split, 'expected a key')
    if (!NAME.test(key)) throw new IniError(line, indent(raw), `invalid key ${key}`)
    const full = section === '' ? key : `${section}.${key}`
    if (values.has(full)) throw new IniError(line, indent(raw), `key ${full} is set twice`)
    const rest = trimmed.slice(split + 1)
    values.set(full, { text: rest.trim(), line, column: valueColumn(raw, split, rest) })
  }
  return values
}

/**
 * Parse the environment layer: one `NAME=VALUE` line per variable.
 * @param {string} text - the whole text read from standard input.
 * @returns {Map<string, {name: string, text: string, line: number, column: number}>} each
 *   variable's raw value with the position it was written at, in the order it was written.
 * @throws {IniError} on the first line the grammar refuses.
 */
export function parseEnv(text) {
  const values = new Map()
  for (const [index, raw] of lines(text).entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const split = trimmed.indexOf('=')
    if (split === -1) throw new IniError(line, indent(raw), 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new IniError(line, indent(raw), 'expected a variable name')
    const rest = trimmed.slice(split + 1)
    values.set(name, { name, text: rest.trim(), line, column: valueColumn(raw, split, rest) })
  }
  return values
}
"}

