{"file_path":"src/schema.js","content":"/** The settings this loader knows, their types, and the text each one defaults to. */

/** Every known setting, in ascending key order. */
export const SETTINGS = [
  { key: 'log.file', type: 'string', default: '' },
  { key: 'log.level', type: 'enum', members: ['debug', 'info', 'warn', 'error'], default: 'info' },
  { key: 'log.rotate', type: 'boolean', default: 'true' },
  { key: 'retry.attempts', type: 'integer', default: '3' },
  { key: 'retry.backoff', type: 'duration', default: '250ms' },
  { key: 'server.host', type: 'string', default: 'localhost' },
  { key: 'server.port', type: 'integer', default: '8080' },
  { key: 'server.timeout', type: 'duration', default: '30s' },
  { key: 'server.tls', type: 'boolean', default: 'false' },
  { key: 'tags', type: 'list', default: '' },
]

const BY_KEY = new Map(SETTINGS.map(declared => [declared.key, declared]))

/**
 * The setting one key names, or undefined when the schema does not know it.
 * @param {string} key - the dotted setting key.
 * @returns {{key: string, type: string, members?: string[], default: string} | undefined} the setting.
 */
export function setting(key) {
  return BY_KEY.get(key)
}

/** The environment variable one setting travels under. */
export function variable(key) {
  return `CONF_${key.toUpperCase().replaceAll('.', '_')}`
}

const BY_VARIABLE = new Map(SETTINGS.map(declared => [variable(declared.key), declared.key]))

/**
 * The setting key one environment variable names, or undefined when none does.
 * @param {string} name - the variable name as it was written.
 * @returns {string | undefined} the dotted setting key.
 */
export function keyOf(name) {
  return BY_VARIABLE.get(name)
}

/** One value that does not fit its setting's declared type. */
export class TypeError_ extends Error {
  constructor(message) {
    super(message)
    this.name = 'SettingTypeError'
  }
}

export { TypeError_ as SettingTypeError }

const INTEGER = /^-?(?:0|[1-9][0-9]*)$/u
const DURATION = /^([0-9]+)(ms|s|m|h)$/u
const UNITS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }

/**
 * Coerce one setting's raw text to the rendering its declared type asks for.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text a layer wrote.
 * @returns {string} the rendered value.
 * @throws {TypeError_} when the text does not fit the type.
 */
export function coerce(declared, text) {
  const { key, type } = declared
  if (type === 'string') return text
  if (type === 'integer') {
    if (!INTEGER.test(text)) throw new TypeError_(`${key} is not an integer: ${text}`)
    return text
  }
  if (type === 'boolean') {
    if (text !== 'true' && text !== 'false') throw new TypeError_(`${key} is not a boolean: ${text}`)
    return text
  }
  if (type === 'enum') {
    if (!declared.members.includes(text)) {
      throw new TypeError_(`${key} is not one of ${declared.members.join('|')}: ${text}`)
    }
    return text
  }
  if (type === 'duration') {
    const match = DURATION.exec(text)
    if (match === null) throw new TypeError_(`${key} is not a duration: ${text}`)
    return String(BigInt(match[1]) * UNITS[match[2]])
  }
  if (type === 'list') {
    if (text === '') return ''
    const items = []
    for (const part of text.split(',')) {
      const item = part.trim()
      if (item === '') throw new TypeError_(`${key} has an empty item: ${text}`)
      if (!items.includes(item)) items.push(item)
    }
    return items.join(',')
  }
  throw new TypeError_(`${key} has an unknown type: ${type}`)
}
"}

