{"file_path":"src/layer.js","content":"/** Stacking layers: the last layer that sets a key wins. */

/**
 * Merge named layers, later over earlier, one key at a time.
 * @param {readonly {name: string, values: Map<string, {text: string, where: string}>}[]} layers -
 *   the layers, weakest first.
 * @returns {Map<string, {text: string, where: string, layer: string}>} each key's winning entry,
 *   naming the layer that set it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) merged.set(key, { ...entry, layer: layer.name })
  }
  return merged
}
"}

