/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  let values
  try {
    values = parseIni(readFileSync(path, 'utf8'))
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
  const entries = new Map()
  for (const [key, entry] of values) {
    entries.set(key, { text: entry.text, where: `${path}:${entry.line}:${entry.column}`, key })
  }
  return { name, values: entries }
}

/** The same layer, refusing any key the schema does not know, in the order the file writes them. */
function strictIniLayer(name, path) {
  const layer = iniLayer(name, path)
  for (const [key, entry] of layer.values) {
    if (setting(key) === undefined) fail(`${entry.where}: unknown setting ${key}`)
  }
  return layer
}

/** The environment layer, read as `NAME=VALUE` lines from standard input. */
function envLayer() {
  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }
  let values
  try {
    values = parseEnv(text, name => keyOf(name) !== undefined)
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
  const entries = new Map()
  for (const entry of values.values()) {
    entries.set(keyOf(entry.name), { text: entry.text, where: `<stdin>:${entry.line}:${entry.column}` })
  }
  return { name: 'env', values: entries }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []
if (mode === 'dump' || mode === 'get') {
  const values = merge([iniLayer('file', argv[1])])
  const raw = key => (values.has(key) ? values.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const base = strictIniLayer('base', argv[1])
  const site = strictIniLayer('site', argv[2])
  const values = merge([base, site, envLayer()])
  for (const declared of SETTINGS) {
    const entry = values.get(declared.key)
    if (mode === 'origin') {
      out.push(`${declared.key} ${entry === undefined ? 'default' : entry.layer}`)
      continue
    }
    const text = entry === undefined ? declared.default : entry.text
    try {
      out.push(`${declared.key}=${coerce(declared, text)}`)
    } catch (error) {
      if (!(error instanceof SettingTypeError)) throw error
      fail(`${entry === undefined ? 'schema' : entry.where}: ${error.message}`)
    }
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
